package br.com.lealinfo.vidraceiro;
import android.app.Activity;import android.graphics.*;import android.graphics.drawable.*;import android.view.View;import org.json.*;import java.io.*;import java.nio.file.Files;
final class PolishFlow {
 static void photo(MeasureFlowInstrumentation t)throws Exception{MainActivity a=t.a;File capture=new File(PhotoAttachment.directory(a,a.current),"capture.jpg");try(InputStream in=t.getContext().getAssets().open("bathroom-cc-by-sa.jpg")){Files.copy(in,capture.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}t.ui(()->{a.pendingPhoto();a.onActivityResult(1,Activity.RESULT_OK,null);});t.check(a.page.equals("project"),"camera-result pipeline returns to project, not isolated photo screen");JSONObject record=a.current.getJSONObject("photoAttachment");t.check(record.getString("projectId").equals(a.current.getString("id")),"photo owns persistent project UUID");t.check(new File(a.photoDir(),"photo.jpg").length()==record.getLong("sizeBytes"),"permanent normalized JPEG matches attachment record");boolean preview=false;for(int i=0;i<a.root.getChildCount();i++)if(a.root.getChildAt(i) instanceof android.widget.ImageView&&((android.widget.ImageView)a.root.getChildAt(i)).getDrawable()!=null)preview=true;t.check(preview,"photo thumbnail visible within actual project controls");t.screenshot("proof-photo-in-project");
 String old=record.getString("id");Bitmap replacement=Bitmap.createBitmap(400,300,Bitmap.Config.ARGB_8888);replacement.eraseColor(0xff37678a);try(FileOutputStream out=new FileOutputStream(capture)){replacement.compress(Bitmap.CompressFormat.JPEG,90,out);}t.ui(()->{a.pendingPhoto();a.onActivityResult(1,Activity.RESULT_OK,null);});t.check(!old.equals(a.current.getJSONObject("photoAttachment").getString("id")),"replacement updates attachment identity");
 t.ui(()->a.photoPage(a.current));t.click("REMOVER FOTO");t.check(t.select(t.getUiAutomation().getRootInActiveWindow(),"REMOVER"),"remove photo requires explicit confirmation");t.waitForIdleSync();t.check(!new File(a.photoDir(),"photo.jpg").exists()&&!a.current.has("photoAttachment"),"remove clears permanent JPEG and project attachment");
 try(InputStream in=t.getContext().getAssets().open("bathroom-cc-by-sa.jpg")){Files.copy(in,capture.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}t.ui(()->{a.pendingPhoto();a.onActivityResult(1,Activity.RESULT_OK,null);a.flush();});
 }
 static void geometry(MeasureFlowInstrumentation t)throws Exception{MainActivity a=t.a;for(String type:new String[]{"Box de banheiro","Janela","Porta","Espelho","Vidro fixo","Divisória","Fechamento","Guarda-corpo","Esquadria"}){final ProjectDrawing[] ref={null};t.ui(()->{a.screen("drawing","Teste geométrico • "+type);ProjectDrawing v=new ProjectDrawing(a,2000,type.equals("Porta")?2200:2000,type.equals("Box de banheiro")?1000:0,2);v.service=type;a.root.addView(v,new android.widget.LinearLayout.LayoutParams(-1,a.px(340)));ref[0]=v;});ProjectDrawing v=ref[0];t.check(v.surfaceCount()==(type.equals("Box de banheiro")?2:1),"typed surfaces: "+type);t.ui(()->{long time=android.os.SystemClock.uptimeMillis();v.dispatchTouchEvent(android.view.MotionEvent.obtain(time,time,0,10,10,0));v.dispatchTouchEvent(android.view.MotionEvent.obtain(time,time+20,2,2000,2000,0));v.dispatchTouchEvent(android.view.MotionEvent.obtain(time,time+40,1,2000,2000,0));});t.check(v.yaw<=65&&v.pitch>=-55,"orbit cannot collapse glass edge-on: "+type);final Bitmap[] frame={null};t.ui(()->{frame[0]=Bitmap.createBitmap(v.getWidth(),v.getHeight(),Bitmap.Config.ARGB_8888);v.draw(new Canvas(frame[0]));});int glass=0;for(int y=50;y<frame[0].getHeight()-40;y++)for(int x=10;x<frame[0].getWidth()-10;x++){int color=frame[0].getPixel(x,y);if(Color.green(color)>65&&Color.blue(color)>90)glass++;}t.check(glass>1500,"non-line rendered glass area: "+type);t.ui(()->{v.setZoom(1.5f);});t.check(v.zoom==1.5f,"zoom: "+type);t.ui(v::reset);if(type.equals("Box de banheiro")||type.equals("Janela")||type.equals("Porta"))t.screenshot("proof-model-"+v.kind());}
 t.ui(()->a.drawing(a.current));}
 static void icon(MeasureFlowInstrumentation t)throws Exception{for(boolean header:new boolean[]{true,false}){Bitmap surface=Bitmap.createBitmap(400,200,Bitmap.Config.ARGB_8888);HomeVisuals.Glass glass=new HomeVisuals.Glass(t.getTargetContext(),0xff22ccff,header);glass.setBounds(0,0,400,200);glass.draw(new Canvas(surface));t.check(Color.alpha(surface.getPixel(0,0))==0&&Color.alpha(surface.getPixel(200,100))>0,"native glass surface has rounded unclipped corners: "+header);}Drawable icon=t.getTargetContext().getPackageManager().getApplicationIcon(t.getTargetContext().getPackageName());t.check(icon instanceof AdaptiveIconDrawable,"installed PackageManager icon is adaptive ANGRA asset");for(int size:new int[]{64,108,192}){Bitmap b=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);Path mask=new Path();mask.addCircle(size/2f,size/2f,size/2f,Path.Direction.CW);c.clipPath(mask);icon.setBounds(0,0,size,size);icon.draw(c);try(FileOutputStream out=new FileOutputStream(new File(t.getTargetContext().getFilesDir(),"proof-icon-"+size+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}t.check(Color.alpha(b.getPixel(size/2,size/2))>0,"adaptive icon renders at density size "+size);int edgeGlyph=0;for(int y=0;y<size;y++)for(int x=0;x<size;x++)if(Color.green(b.getPixel(x,y))>130&&Math.hypot(x-size/2.,y-size/2.)>size*.44)edgeGlyph++;t.check(edgeGlyph==0,"AV foreground stays inside circular launcher safe area "+size);}}
 static void create(MeasureFlowInstrumentation t)throws Exception{photo(t);geometry(t);icon(t);t.ui(()->t.a.home());t.screenshot("proof-premium-home");}
 static void verify(MeasureFlowInstrumentation t)throws Exception{MainActivity a=t.a;JSONObject p=a.current,attachment=p.getJSONObject("photoAttachment");File image=new File(PhotoAttachment.directory(a,p),"photo.jpg");t.check(image.exists()&&image.length()==attachment.getLong("sizeBytes"),"photo survives force-stop and new process");t.check(attachment.getString("projectId").equals(p.getString("id")),"photo association survives restart");t.check(a.exportData(p).getJSONObject("project").getJSONObject("photoAttachment").getString("sha256").equals(attachment.getString("sha256")),"structured PDV export includes attachment hash, not temporary URI");t.ui(()->a.editProject(p));t.screenshot("proof-photo-reopened");}
}
